def lda_fit(X, y, alpha):
    mu = X.mean(0); Xc = X - mu
    means = np.stack([Xc[y==c].mean(0) for c in range(8)])
    R = Xc - means[y]
    S = R.T@R/len(y)
    S = (1-alpha)*S + alpha*np.trace(S)/S.shape[0]*np.eye(S.shape[0])
    Wt = np.linalg.solve(S, means.T).T
    b = -0.5*np.sum(Wt*means,1) - Wt@mu
    return Wt, b
def ridge_fit(X,y,lam):
    mu=X.mean(0); sd=X.std(0)+1e-6; Z=(X-mu)/sd
    T=np.eye(8)[y]-1/8
    A=np.linalg.solve(Z.T@Z+lam*np.eye(Z.shape[1]), Z.T@T)
    Wt=(A/sd[:,None]).T; b=T.mean(0)+1/8 - Wt@mu
    return Wt,b
def cv(X, fit, p):
    pred=np.zeros(len(y),int)
    for f in range(5):
        tr=folds!=f; Wt,b=fit(X[tr],y[tr],p); pred[~tr]=np.argmax(X[~tr]@Wt.T+b,1)
